package br.com.sussmartcare.telemetry.domain; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="telemetry_sessions") public class TelemetrySession { @Id private UUID id; @Column(nullable=false) private UUID patientId; private UUID visitId; private UUID preHospitalEncounterId; @Column(nullable=false) private String sourceContext; @Column(nullable=false) private Instant startedAt; private Instant endedAt; protected TelemetrySession(){} public TelemetrySession(UUID patientId,UUID visitId,UUID preHospital,String source){id=UUID.randomUUID();this.patientId=patientId;this.visitId=visitId;this.preHospitalEncounterId=preHospital;sourceContext=source;startedAt=Instant.now();} public UUID getId(){return id;} public UUID getPatientId(){return patientId;} public UUID getVisitId(){return visitId;} public UUID getPreHospitalEncounterId(){return preHospitalEncounterId;} public String getSourceContext(){return sourceContext;} public Instant getStartedAt(){return startedAt;} public Instant getEndedAt(){return endedAt;} }